341	/// `Authorization: Bearer …` matches the static token or a live OAuth token.
342	fn authorized(req: &Request, shared: &Shared, oauth: Option<&OAuth>) -> bool {
343	    if shared.auth == AuthMode::None {
344	        return true;
345	    }
346	    let token = header(req, "Authorization").and_then(|v| {
347	        let (scheme, rest) = v.trim().split_once(' ')?;
348	        scheme.eq_ignore_ascii_case("bearer").then(|| rest.trim())
349	    });
350	    let Some(token) = token else { return false };
351	    shared.token.as_deref().is_some_and(|t| oauth::same(t, token))
352	        || oauth.is_some_and(|o| o.check_access(token))
353	}
