355	fn unauthorized(oauth: Option<&OAuth>) -> Out {
356	    let mut out = Out::error(401, "missing or invalid bearer token");
357	    let challenge = match oauth {
358	        Some(o) => o.www_authenticate(),
359	        None => "Bearer realm=\"leviathan\"".into(),
360	    };
361	    out.headers.push(("WWW-Authenticate", challenge));
362	    out
363	}
