365	fn basic_auth(req: &Request) -> Option<(String, String)> {
366	    let (scheme, rest) = header(req, "Authorization")?.trim().split_once(' ')?;
367	    if !scheme.eq_ignore_ascii_case("basic") {
368	        return None;
369	    }
370	    let decoded = base64::engine::general_purpose::STANDARD.decode(rest.trim()).ok()?;
371	    let text = String::from_utf8(decoded).ok()?;
372	    let (id, secret) = text.split_once(':')?;
373	    Some((oauth::percent_decode(id), oauth::percent_decode(secret)))
374	}
